insert into public.modulos (numero, slug, titulo, resumen, publicado) values (0, 'introduccion', 'Introducción y principios del curso', 'De qué trata el curso, cómo está organizado y los criterios que guían todos los módulos.', true);
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 1, 'de-que-trata-este-curso', '¿De qué trata este curso?' from public.modulos where numero = 0;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Un recorrido por el cielo desde <strong>dos miradas complementarias</strong> y, sobre todo, desde <strong>muchas culturas y épocas</strong>:</p>\n<ul><li><p><strong>Astronomía</strong>: la ciencia moderna de las estrellas, los planetas y el cosmos (la visión de la NASA y la física actual).</p></li><li><p><strong>Astrología</strong>: el lenguaje simbólico que relaciona los astros con la personalidad, el tiempo y los acontecimientos.</p></li></ul>\n<p>Y todo ello <strong>comparando cosmovisiones</strong>: cómo egipcios, babilonios, griegos, romanos, mayas, chinos y la tradición védica entendieron el cielo, incluyendo modelos geocéntricos y de tierra plana, junto a lo que sostiene hoy la astronomía moderna.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 0 and s.orden = 1;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 2, 'principios-del-curso', 'Principios del curso' from public.modulos where numero = 0;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Estos criterios guían <strong>todos</strong> los módulos:</p>\n<ul><li><p><strong>Libre albedrío</strong>: el curso no decide por ti qué cosmovisión es la verdadera. Expone cada una con su propia lógica, sus argumentos y sus fuentes, y eres tú quien saca sus conclusiones.</p></li><li><p><strong>Estructura de menos a más</strong>: cada módulo va de una introducción accesible, a un desarrollo de los conceptos clave, a una capa avanzada más profunda.</p></li><li><p><strong>La capa avanzada siempre documentada</strong>: toda afirmación de la parte avanzada se apoya en fuentes fidedignas y verificables (textos originales, obras académicas, datos astronómicos publicados).</p></li><li><p><strong>Verificable no significa \"verdadero por defecto\"</strong>: que una fuente sea verificable no la hace más cierta que otra. La visión moderna no tiene prioridad por ser la oficial.</p></li><li><p><strong>Cada afirmación atribuida a quien la sostiene</strong>: en lugar de \"esto es así\", diremos \"la cosmología moderna sostiene esto, según tal evidencia\" o \"la tradición egipcia sostenía esto otro, según tales textos\". Todas las visiones tienen el mismo rango; se especifica quién le da autoridad a cada una.</p></li><li><p><strong>Hecho frente a creencia</strong>: en los temas esotéricos y místicos se distingue con claridad entre un hecho histórico documentado y una creencia o interpretación simbólica.</p></li><li><p><strong>Módulo fundacional</strong>: \"Mirar el cielo\" es el más desarrollado, porque da la visión global y el vocabulario para entender todo lo demás. Los fenómenos observables se explican desde ambas cosmovisiones, la moderna y la terraplanista, lado a lado. Los demás módulos se profundizan sobre la marcha, según el interés.</p></li><li><p><strong>Hilo conductor histórico, sin fundir las visiones</strong>: un eje temporal muestra cómo se pasó de una cosmovisión a otra, pero cada una se presenta con su postura clara y su coherencia propia; ninguna se trata como la \"equivocada\" que otra vino a corregir.</p></li><li><p><strong>La arquitectura del cielo de cada tradición, aquí; su lado místico, en el módulo 8</strong>: en los módulos de observación, cada fenómeno se explica desde todas las cosmovisiones en pie de igualdad: la astronomía moderna, el modelo terraplanista, la cosmología bíblica y cabalística, el Libro de Enoc (con especial atención), la cristiana medieval, y las de sumerios, babilonios, egipcios, griegos y romanos. Solo se compara cómo entendía cada una la estructura física del cosmos. Los significados simbólicos y espirituales se reservan para el módulo 8.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 0 and s.orden = 2;
insert into public.modulos (numero, slug, titulo, resumen, publicado) values (1, 'mirar-el-cielo', 'Mirar el cielo', 'Qué vemos realmente a simple vista: estrellas, Sol, Luna, eclipses, planetas y zodiaco, explicados desde cada cosmovisión.', true);
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 1, 'introduccion-que-vemos-cuando-miramos-el-cielo', 'Introducción: qué vemos cuando miramos el cielo' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Antes de cualquier teoría, está lo que cualquier persona ve con sus propios ojos. Si te quedas una noche entera mirando el cielo, notas algo asombroso: casi todas las estrellas se mueven, trazando arcos lentos de un lado al otro, mientras una sola parece quedarse quieta. En el hemisferio norte esa estrella es <strong>Polaris</strong>, la estrella polar, y las demás giran en círculos a su alrededor.</p>\n<p>Este es el <strong>módulo fundacional</strong> del curso, el más desarrollado, porque aquí aprendemos a observar y a nombrar lo que vemos: el movimiento de las estrellas, el camino del Sol, las fases de la Luna, los planetas que vagan entre las constelaciones. Es el vocabulario con el que entenderemos todo lo demás.</p>\n<p>Y lo haremos con una regla de oro: <strong>separar lo que se observa de cómo se explica</strong>. El movimiento de Polaris es un hecho que cualquiera puede comprobar. Por qué ocurre es ya una explicación, y de esas hay varias. A lo largo del módulo pondremos lado a lado las explicaciones de distintas cosmovisiones (la astronomía moderna, el modelo terraplanista, la cosmología bíblica y cabalística, la cristiana medieval y las de sumerios, egipcios, griegos y romanos), cada una con su propia lógica, para que veas cómo un mismo cielo admite lecturas distintas. Ninguna se presenta aquí como la verdadera: cada una se expone con sus propios argumentos, y la conclusión es tuya.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 1;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 2, 'como-esta-organizado-este-modulo', 'Cómo está organizado este módulo' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Como todos los módulos del curso, este va <strong>de menos a más</strong>, en tres capas:</p>\n<ol><li><p><strong>Introducción accesible</strong> (la que acabas de leer): el cielo a simple vista, sin tecnicismos, para despertar la mirada.</p></li><li><p><strong>Desarrollo de los conceptos clave</strong>: aquí nombramos y entendemos los grandes fenómenos observables — el movimiento diario de las estrellas y Polaris, el recorrido anual del Sol y la eclíptica, las fases de la Luna, el vagar de los planetas, las constelaciones y cómo orientarse. Cada fenómeno se describe primero como observación, y luego se explica desde cada una de las cosmovisiones del curso.</p></li><li><p><strong>Capa avanzada documentada</strong>: la parte más profunda, donde entramos en los detalles (ángulos, mediciones, cómo se predicen los fenómenos) y donde <strong>toda afirmación va con su fuente verificable</strong>, atribuida a quien la sostiene. Ninguna visión se da por verdadera por defecto.</p></li></ol>\n<p>Así puedes quedarte en la capa que quieras según tu interés, o recorrerlas todas en orden.</p>\n<p>Junto al texto encontrarás imágenes y animaciones. Cada una lleva una etiqueta que dice qué es:</p>\n<ul><li><p><strong>Fotografía real</strong>: tomada con una cámara, con su autor, su licencia y su fuente.</p></li><li><p><strong>Obra histórica</strong>: un grabado, un mapa o un manuscrito de época, con su fecha.</p></li><li><p><strong>Esquema</strong>, <strong>animación</strong> o <strong>interactivo</strong>: un dibujo hecho para este curso, simplificado a propósito, que indica qué modelo representa.</p></li><li><p><strong>Imagen generada por IA</strong>: por ahora no hay ninguna; si alguna vez se usa, se dirá expresamente.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 2;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 3, 'las-palabras-basicas-para-mirar-el-cielo', 'Las palabras básicas para mirar el cielo' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Antes de comparar explicaciones necesitamos un vocabulario común. No hace falta saber nada de antemano: aquí se explica todo desde el principio.</p>\n<p>Algunas palabras nombran cosas que cualquiera ve desde donde está, como el horizonte o los puntos cardinales. Otras, como la latitud o el polo celeste, son herramientas para situarse, y cada modelo del mundo las dibuja a su manera. Por eso cada término se explica primero tal como se usa en la práctica, y después cómo lo representa cada modelo.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>Lo que ves desde donde estás: horizonte, cenit y puntos cardinales</h3>\n<p>Imagina que estás en un campo abierto, de noche, lejos de las luces.</p>\n<ul><li><p><strong>Horizonte</strong>: la línea donde parecen juntarse el cielo y el suelo, a tu alrededor.</p></li><li><p><strong>Cenit</strong>: el punto del cielo que queda justo encima de tu cabeza. Si te tumbas boca arriba, miras al cenit.</p></li><li><p><strong>Puntos cardinales</strong>: norte, sur, este y oeste. El Sol sale aproximadamente por el este y se pone por el oeste. Desde España, a mediodía, el Sol está hacia el sur.</p></li><li><p><strong>Altura de un astro</strong>: cuánto se levanta sobre el horizonte, medido en grados. Una estrella en el horizonte está a 0°; una en el cenit, a 90°; una a medio camino, a 45°.</p></li></ul>\n<p>Un truco para medir la altura sin instrumentos: estira el brazo y cierra el puño. Visto así, un puño tapa unos 10° de cielo. Del horizonte al cenit caben unos nueve puños.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'interactivo', '{"componente": "cielo-local", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "Mueve la altura del astro y mira cuántos puños hay desde el horizonte."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'texto', '{"html": "<h3>Hemisferios, ecuador, latitud y longitud</h3>\n<p>Para decir dónde está un lugar de la Tierra se usan dos números: la <strong>latitud</strong> y la <strong>longitud</strong>. Son los que dan el GPS del móvil, los mapas y las cartas de navegación. Los usan todos los modelos actuales del mundo; lo que cambia es cómo los dibujan.</p>\n<ul><li><p><strong>Ecuador</strong>: la línea que divide la Tierra en dos mitades, la norte y la sur. Pasa, por ejemplo, por Ecuador, Brasil, Kenia e Indonesia.</p></li><li><p><strong>Hemisferio norte y hemisferio sur</strong>: cada una de esas dos mitades. España, México o Japón están en el hemisferio norte; Argentina, Chile, Sudáfrica o Australia, en el sur.</p></li><li><p><strong>Latitud</strong>: lo al norte o al sur que estás del ecuador, en grados. En el ecuador es 0°; en el Polo Norte, 90° norte; en el Polo Sur, 90° sur. Madrid está a unos 40° norte y Buenos Aires a unos 35° sur.</p></li><li><p><strong>Paralelos</strong>: las líneas que unen los lugares con la misma latitud. El ecuador es uno de ellos.</p></li><li><p><strong>Longitud</strong>: lo al este o al oeste que estás, también en grados, contando desde una línea elegida como punto de partida: el meridiano de Greenwich, en Londres, fijado como 0° por un acuerdo internacional de 1884. Va de 0° a 180° hacia el este y hacia el oeste. Madrid está a unos 4° oeste.</p></li><li><p><strong>Meridianos</strong>: las líneas que unen los lugares con la misma longitud. Van de norte a sur.</p></li><li><p><strong>Polo Norte y Polo Sur</strong>: los dos extremos, a 90° de latitud.</p></li></ul>\n<p><strong>Cómo lo dibuja el modelo del globo.</strong> La Tierra es una esfera. Los meridianos son semicírculos que van de un polo al otro, y los paralelos son círculos cada vez más pequeños a medida que se acercan a los polos, que son dos puntos. La latitud se define como un ángulo medido desde el centro de la esfera.</p>\n<p><strong>Cómo lo dibuja el modelo plano.</strong> En el mapa de un solo centro, como el de Gleason de 1892, el Polo Norte está en el centro de un gran disco. Los meridianos son líneas rectas que salen del centro, como los radios de una rueda, y los paralelos son círculos alrededor del centro, cada vez más grandes hacia fuera. El ecuador es un círculo intermedio, y el sur no es un punto sino el borde exterior, ocupado por un anillo de hielo: lo que en el globo es la Antártida. La latitud se interpreta como la distancia al centro. Los defensores del modelo bipolar dibujan dos centros en lugar de uno.</p>\n<p>Cada modelo calcula de forma distinta algunas distancias, sobre todo en el hemisferio sur. Ese es uno de los puntos que se comparan en la capa avanzada.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'interactivo', '{"componente": "mapa-dos-modelos", "etiqueta": "Interactivo", "modelo": "Dos modelos: globo y plano", "pie": "El mismo mundo dibujado por los dos modelos. Elige un lugar o mueve la latitud y la longitud: en dorado, su paralelo y su meridiano. Continentes: Natural Earth, simplificados."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'texto', '{"html": "<h3>El cielo como una cúpula: polos celestes y ecuador celeste</h3>\n<p>De noche, el cielo parece una gran cúpula que nos envuelve, sembrada de estrellas que giran lentamente. Los astrónomos de todas las épocas han dibujado esa cúpula como una esfera alrededor del observador, la <strong>esfera celeste</strong>, para poder situar las estrellas. Unos la consideraban algo real y otros solo una herramienta de dibujo, pero el vocabulario es el mismo.</p>\n<ul><li><p><strong>Polo celeste</strong>: el punto del cielo alrededor del cual parecen girar todas las estrellas durante la noche. No es un objeto, sino un lugar del cielo, como el centro de una rueda. Hay dos. El <strong>polo norte celeste</strong> está muy cerca de la estrella Polaris, que por eso parece quieta. El <strong>polo sur celeste</strong> no tiene ninguna estrella brillante al lado; la más próxima, Sigma Octantis, apenas se ve a simple vista.</p></li><li><p><strong>Ecuador celeste</strong>: la línea del cielo que queda a medio camino entre los dos polos celestes. Las estrellas que están sobre ella salen exactamente por el este y se ponen exactamente por el oeste.</p></li><li><p><strong>Estrellas circumpolares</strong>: las que, vistas desde un lugar, nunca llegan a ponerse, porque su círculo alrededor del polo queda siempre por encima del horizonte.</p></li></ul>\n<p><strong>Un hecho que cualquiera puede medir.</strong> La altura del polo celeste sobre el horizonte coincide, aproximadamente, con la latitud del lugar. Desde Madrid, el polo norte celeste está a unos 40° de altura; desde el ecuador, a ras del horizonte; desde el Polo Norte, en el cenit. Al cruzar el ecuador hacia el sur, el polo norte celeste desaparece bajo el horizonte y empieza a verse el polo sur celeste. Los navegantes portugueses del siglo XV ya medían la altura de Polaris para saber a qué latitud estaban.</p>\n<p><strong>Cómo lo explica el modelo del globo.</strong> El polo celeste es la prolongación hacia el cielo del eje sobre el que gira la Tierra. Como el observador está sobre una superficie curva, al viajar hacia el sur su horizonte se va inclinando y el polo norte celeste baja; al cruzar el ecuador, queda oculto y aparece el polo sur celeste.</p>\n<p><strong>Cómo lo explica el modelo plano.</strong> Polaris está a cierta altura sobre el centro del disco. Al alejarse del centro, la perspectiva la hace bajar hacia el horizonte, como una farola que parece más baja cuanto más te alejas. Para el polo sur celeste hay varias propuestas, que se explican en el apartado de Polaris.</p>\n<p><strong>Cómo lo explicaban los modelos de esferas de la Antigüedad.</strong> Para Aristóteles, Ptolomeo o la astronomía medieval, la Tierra es una esfera inmóvil y lo que gira es el cielo, alrededor de un eje que pasa por los polos celestes. La geometría de la altura del polo es la misma que en el globo moderno; lo que cambia es qué se mueve.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 7, 'interactivo', '{"componente": "donde-apuntar", "etiqueta": "Interactivo", "modelo": "Observación y dos modelos: globo y plano", "pie": "Arriba, lo que ves y hacia dónde apuntar la cámara según la latitud. Abajo, cómo dibuja esa misma situación cada modelo. Esquemas, no a escala."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 3;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 4, 'los-grandes-modelos-del-mundo-y-quien-los-uso', 'Los grandes modelos del mundo y quién los usó' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>A lo largo de la historia, cada cultura ha descrito la forma del mundo y del cielo a su manera. Antes de recorrerlas conviene tener un mapa de las grandes respuestas, para saber de qué hablamos cada vez que el curso compara modelos.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>Dos preguntas, cuatro respuestas</h3>\n<p>Todos los modelos responden, de una u otra manera, a dos preguntas distintas que conviene no mezclar:</p>\n<ol><li><p><strong>¿Qué forma tiene la Tierra?</strong> Plana o esférica.</p></li><li><p><strong>¿Qué está quieto en el centro?</strong> La Tierra, con el Sol y los astros girando a su alrededor (modelo <strong>geocéntrico</strong>, de la palabra griega para tierra), o el Sol, con la Tierra girando a su alrededor (modelo <strong>heliocéntrico</strong>, de la palabra griega para sol).</p></li></ol>\n<p>Al combinar las respuestas salen cuatro posibilidades:</p>\n<ul><li><p><strong>Tierra plana y geocéntrica</strong>: la tierra es una superficie bajo la bóveda del cielo, y el Sol, la Luna y las estrellas giran por encima de ella. Es el modelo de la mayoría de las culturas antiguas y del movimiento actual de la Tierra plana.</p></li><li><p><strong>Tierra esférica y geocéntrica</strong>: la Tierra es una esfera inmóvil en el centro, y el cielo gira a su alrededor. Es el modelo de Aristóteles, de Ptolomeo, de la Edad Media cristiana, judía e islámica, y de los geocentristas actuales. Una variante, la de Tycho Brahe (1588), pone a los planetas girando alrededor del Sol, y al Sol girando alrededor de la Tierra.</p></li><li><p><strong>Tierra esférica y heliocéntrica</strong>: la Tierra gira sobre sí misma cada día y alrededor del Sol cada año. Lo propuso Aristarco de Samos en el siglo III a. C., lo recuperó Copérnico en 1543 y es el modelo de la astronomía moderna, que además sostiene que el Sol tampoco es el centro del universo, sino una estrella entre muchas.</p></li><li><p><strong>Tierra plana y heliocéntrica</strong>: no se conoce ninguna tradición que la haya defendido.</p></li></ul>\n<p>Hay culturas de las que no se conserva ninguna descripción de la forma de la Tierra. Cuando es así, el curso lo dice en lugar de suponerla.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'interactivo', '{"componente": "cuatro-modelos", "etiqueta": "Interactivo", "modelo": "Los cuatro modelos", "pie": "Las dos preguntas combinadas. Toca un modelo para ver qué culturas lo usaron."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'interactivo', '{"componente": "linea-tiempo", "etiqueta": "Interactivo", "modelo": "Línea del tiempo", "pie": "Qué modelo usó cada cultura, de la más antigua a hoy. Dos franjas en una barra: convivieron dos modelos o su lectura se debate. El detalle está en el texto que sigue."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>Quién usó cada modelo, por orden cronológico</h3>\n<p>Cada entrada dice de qué época es, qué modelo usaba y en qué fuentes se apoya lo que sabemos. Las fechas son aproximadas. Cuando los especialistas discuten la interpretación, se indica.</p>\n<p><strong>Sumerios y babilonios</strong> (Mesopotamia, desde hacia el 3000 a. C.). <em>Tierra plana y geocéntrica</em>, según la lectura habitual de sus textos: el cielo, An, sobre la tierra, Ki, y la tierra rodeada de agua. El llamado mapa babilónico del mundo, una tablilla del siglo VI a. C. que se conserva en el Museo Británico, dibuja la tierra como un disco rodeado por un río salado. Los textos no dan una geometría completa: la reconstrucción es de los especialistas.</p>\n<p><strong>Egipcios</strong> (desde hacia el 3000 a. C. hasta el 30 a. C.). <em>Tierra plana y geocéntrica</em>: el dios Geb es la tierra, tendida bajo la diosa Nut, el cielo, arqueada sobre ella, y el dios Shu, el aire, los separa. De noche, el Sol recorre la Duat, el mundo inferior. Fuentes: los Textos de las Pirámides, el Libro de Nut y las pinturas de los techos de templos y tumbas.</p>\n<p><strong>Antiguos hebreos</strong> (I milenio a. C.). <em>Geocéntrica; la forma, debatida.</em> La Biblia hebrea describe un firmamento, el <em>raqia</em>, que separa las aguas de arriba de las de abajo, y una tierra firme que «no se moverá» (Salmo 104:5). Sobre su forma hay lecturas distintas: Isaías 40:22 habla del «círculo de la tierra», que unos entienden como un disco y otros como una esfera, y Job 26:7 dice que Dios «cuelga la tierra sobre la nada».</p>\n<p><strong>India védica</strong> (II y I milenio a. C.). <em>Tierra plana y geocéntrica</em> en los himnos del Rigveda, que hablan del cielo, Dyaus, y de la tierra, Prithvi, como dos mitades del mundo. La India tuvo después otros modelos, que aparecen más abajo.</p>\n<p><strong>China tradicional</strong> (desde el I milenio a. C.). <em>Geocéntrica, con varios modelos que convivieron.</em> El más antiguo, el <em>gaitian</em> («el cielo como una cubierta»), recogido en el <em>Zhoubi suanjing</em> hacia el siglo I a. C., describe un cielo redondo como una sombrilla sobre una tierra plana y cuadrada. El <em>huntian</em> («el cielo que envuelve»), que Zhang Heng explicó en el siglo II d. C., compara el cielo con un huevo y la tierra con la yema; los historiadores discuten si esa tierra se imaginaba plana o redondeada. El <em>xuanye</em> describía los astros flotando en un espacio vacío e ilimitado. El mapa de la Tierra esférica llegó a China con los jesuitas, como el mapamundi de Matteo Ricci de 1602.</p>\n<p><strong>Griegos</strong> (del siglo VIII al I a. C.). <em>Pasaron de la Tierra plana a la esférica, casi siempre geocéntrica.</em> En Homero y Hesíodo, la tierra es plana y está rodeada por el río Océano. Tales la imaginó flotando sobre el agua, y Anaximandro, como un cilindro. Desde el siglo V a. C., los pitagóricos y Parménides la describen esférica, y Platón y Aristóteles la sitúan esférica e inmóvil en el centro del cosmos. Hubo voces distintas: Filolao puso en el centro un fuego, y Aristarco de Samos, en el siglo III a. C., el Sol.</p>\n<p><strong>Celtas</strong> (lo que sabemos procede de autores griegos y romanos del siglo I a. C. en adelante). <em>Modelo no documentado.</em> Julio César (<em>La guerra de las Galias</em>, VI, 14) y Pomponio Mela cuentan que los druidas enseñaban sobre las estrellas y sus movimientos y sobre el tamaño del mundo y de la tierra, pero no dicen qué forma le daban. Los druidas no dejaron escritos. Se conserva un calendario galo en bronce, el de Coligny, del siglo II d. C., que combina meses lunares con el año solar.</p>\n<p><strong>Romanos</strong> (del siglo I a. C. al V d. C.). <em>Tierra esférica y geocéntrica</em>, heredada de los griegos. Plinio el Viejo defiende la Tierra esférica en su <em>Historia natural</em> (libro II); Cicerón describe en <em>El sueño de Escipión</em> nueve esferas celestes, y Ptolomeo, en el <em>Almagesto</em> (siglo II d. C.), fija el modelo geocéntrico de esferas que se usará durante unos catorce siglos.</p>\n<p><strong>Mayas</strong> (sobre todo del 250 al 900 d. C.). <em>Tierra plana y geocéntrica</em> en sus representaciones: un cosmos en capas, con trece niveles de cielo y nueve de inframundo, y una superficie terrestre con cuatro rumbos y un centro marcado por un gran árbol, la ceiba. Fuentes: inscripciones, cerámica, el <em>Popol Vuh</em> (puesto por escrito en el siglo XVI) y el Códice de Dresde, con tablas muy precisas de Venus.</p>\n<p><strong>Judaísmo rabínico</strong> (del siglo III al VI d. C., y después). <em>Geocéntrico; la forma, debatida dentro de la propia tradición.</em> El Talmud recoge discusiones sobre el recorrido del Sol de noche (Pesajim 94b). En el siglo XII, Maimónides adopta el modelo esférico de Ptolomeo.</p>\n<p><strong>Cristianos de la Antigüedad tardía y la Edad Media</strong> (del siglo IV al XV). <em>Mayoritariamente Tierra esférica y geocéntrica.</em> Beda el Venerable (siglo VIII), el <em>De sphaera</em> de Sacrobosco (siglo XIII), Tomás de Aquino y Dante describen la Tierra esférica en el centro de las esferas celestes. Hubo voces que defendieron una tierra plana: Lactancio (siglo IV) rechazó la redondez de la Tierra, y Cosmas Indicopleustes (siglo VI) la describió con forma de tabernáculo. San Agustín dudaba de que existieran habitantes en las antípodas, no de la forma esférica.</p>\n<p><strong>India purānica y astronómica</strong> (I milenio d. C.). <em>Dos modelos a la vez.</em> Los Puranas, como el Bhagavata Purana, describen el Bhu-mandala, un gran disco con el monte Meru en el centro rodeado de continentes y océanos en anillos; unos lo leen como una tierra plana literal y otros como un mapa simbólico o cosmológico. Al mismo tiempo, los tratados astronómicos, los <em>siddhantas</em>, describen una Tierra esférica en el centro del cosmos; Aryabhata (499 d. C.) propuso además que gira sobre su eje cada día.</p>\n<p><strong>Mundo islámico medieval</strong> (del siglo VIII al XV). <em>Tierra esférica y geocéntrica</em>, a partir de Ptolomeo traducido al árabe. Al-Biruni (siglo XI) calculó el radio de la Tierra, y los astrónomos de Maragha, como al-Tusi (siglo XIII), y de Damasco, como Ibn al-Shatir (siglo XIV), perfeccionaron los modelos de las esferas.</p>\n<p><strong>Cábala</strong> (desde el siglo XII). <em>Su interés principal es simbólico; en lo físico, convivió con varios modelos.</em> El <em>Zóhar</em> (Castilla, finales del siglo XIII) contiene un pasaje según el cual la tierra gira como una esfera y es de día para unos mientras es de noche para otros. Los cabalistas medievales, en general, aceptaban el modelo esférico de Ptolomeo. El significado de su cosmología se trata en el módulo 8.</p>\n<p><strong>Aztecas o mexicas</strong> (siglos XIV a XVI). <em>Tierra plana y geocéntrica</em> en sus representaciones: el cielo en niveles (nueve, doce o trece según las fuentes), sostenido por cuatro portadores en los puntos cardinales; el Mictlan, el inframundo, debajo; y la tierra como una superficie con cuatro rumbos y un centro, formada, según el mito, a partir del cuerpo de un gran monstruo de la tierra, Cipactli o Tlaltecuhtli. Fuentes: el Códice Vaticano A, el Códice Florentino de Sahagún y la <em>Historia de los mexicanos por sus pinturas</em>, todos del siglo XVI.</p>\n<p><strong>Incas</strong> (siglos XV y XVI). <em>Modelo físico no documentado.</em> Las crónicas coloniales hablan de tres mundos: el Hanan Pacha, de arriba; el Kay Pacha, este mundo; y el Uku Pacha, el de abajo. No describen la forma geométrica de la tierra, y algunos especialistas creen que esa división en tres tiene influencia de los misioneros. Los incas observaban con detalle la Vía Láctea, el Mayu o «río», y sus manchas oscuras, a las que daban forma de animales. Fuentes: Guamán Poma de Ayala, el Inca Garcilaso de la Vega y Juan de Santa Cruz Pachacuti Yamqui, de principios del siglo XVII.</p>\n<p><strong>La revolución copernicana</strong> (siglos XVI y XVII). <em>Del geocentrismo esférico al heliocentrismo esférico, con un modelo intermedio.</em> Copérnico publica en 1543 su modelo con el Sol en el centro. Tycho Brahe propone en 1588 su modelo mixto, con la Tierra quieta. Kepler describe en 1609 órbitas elípticas, Galileo observa con el telescopio en 1610 las lunas de Júpiter y las fases de Venus, y Newton publica en 1687 su teoría de la gravedad. La Iglesia católica prohibió en 1616 defender el movimiento de la Tierra y condenó a Galileo en 1633; retiró esos libros de su índice de libros prohibidos en el siglo XIX, y en 1992 el papa Juan Pablo II reconoció el error del proceso a Galileo.</p>\n<p><strong>Masonería</strong> (desde 1717 en Londres; el grado 33 es el más alto del Rito Escocés Antiguo y Aceptado, organizado en 1801 en Charleston, Estados Unidos). <em>No tiene un modelo cosmológico propio documentado.</em> Su simbolismo usa mucho el cielo: el techo estrellado de la logia, el Sol y la Luna, y, desde el siglo XVIII, dos columnas rematadas con un globo celeste y un globo terrestre, es decir, con la Tierra representada como esfera. Algunos autores actuales sostienen que en los grados altos se transmite una doctrina distinta sobre la forma de la Tierra, pero no se conocen documentos masónicos que la recojan. El significado de su simbolismo astral se trata en el módulo 8.</p>\n<p><strong>Astronomía moderna</strong> (desde el siglo XVIII hasta hoy). <em>Tierra esférica y heliocéntrica</em>: la Tierra, ligeramente achatada por los polos, gira sobre sí misma y alrededor del Sol, que es una estrella entre los cientos de miles de millones de la Vía Láctea. Es el modelo que enseñan las universidades y usan agencias como la NASA o la ESA.</p>\n<p><strong>Movimiento moderno de la Tierra plana</strong> (desde el siglo XIX). <em>Tierra plana y geocéntrica</em>, con variantes: un solo centro o dos. Samuel Rowbotham presentó su «astronomía zetética» en 1849 y la desarrolló en <em>Earth Not a Globe</em> (1865, ampliado en 1881). Le siguieron, entre otros, Wilbur Glenn Voliva en Zion (Illinois) en los años veinte y treinta, Samuel Shenton, fundador en 1956 de la International Flat Earth Research Society, y Charles K. Johnson, su presidente desde 1972. La Flat Earth Society actual se refundó en 2004, y desde 2014 el modelo se ha difundido mucho por internet.</p>\n<p><strong>Cristianos de hoy</strong> (siglos XIX a XXI). <em>Mayoritariamente Tierra esférica y heliocéntrica</em>: las grandes iglesias aceptan el modelo de la astronomía moderna. Algunas minorías de lectura bíblica literal defienden el geocentrismo o la Tierra plana.</p>\n<p><strong>Geocentrismo moderno</strong> (siglos XX y XXI). <em>Tierra esférica y geocéntrica.</em> Algunos autores y grupos cristianos, como Gerardus Bouw o Robert Sungenis, defienden que la Tierra es una esfera inmóvil en el centro del universo, a menudo con una disposición parecida a la de Tycho Brahe.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'texto', '{"html": "<h3>Cómo se ha hecho esta lista</h3>\n<p>Para cada cultura se ha buscado lo que dicen sus propios textos, imágenes y objetos, y lo que concluyen los especialistas que los estudian. Cuando las fuentes no describen la forma de la Tierra, se dice; cuando su interpretación está discutida, se indica quién sostiene cada lectura. El orden es cronológico, pero no es una carrera: pasar de un modelo a otro no se presenta aquí como un error corregido, sino como un cambio de cosmovisión, y cada modelo se expone con su propia lógica. Los módulos 3, 4, 5 y 8 desarrollan cada tradición con más detalle.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 4;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 5, 'el-movimiento-de-las-estrellas-y-el-misterio-de-polaris', 'El movimiento de las estrellas y el misterio de Polaris' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<p>Si apuntas una cámara al cielo nocturno del hemisferio norte y dejas el obturador abierto varias horas, las estrellas no salen como puntos, sino como <strong>arcos de círculo</strong>. Y todos esos arcos comparten un mismo centro: un punto casi inmóvil junto al cual hay una estrella brillante, Polaris. Cuanto más cerca de ella, más pequeño el arco; las estrellas muy próximas apenas se mueven, y Polaris casi nada. Esto es un <strong>hecho observable</strong>, comprobable por cualquiera, en cualquier época, y así lo registraron todas las culturas.</p>\n<p>Un segundo hecho: según cuán al norte o al sur te encuentres, Polaris aparece más alta o más baja en el cielo. En el ecuador queda justo en el horizonte; según subes hacia el norte, sube contigo.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'animacion', '{"componente": "arcos-polaris", "etiqueta": "Animación", "modelo": "Observación", "pie": "Una noche mirando al polo celeste, en el hemisferio norte y en el sur: las estrellas dejan arcos en torno a cada polo. Cambia de hemisferio con los botones."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'imagen', '{"tipo": "foto", "url": "https://noirlab.edu/public/media/archives/images/screen/iotw2033a.jpg", "enlace": "https://kpno.noirlab.edu/images/iotw2033a/", "pie": "Hemisferio norte: fotografía de larga exposición en el observatorio de Kitt Peak (Arizona). Las estrellas trazan arcos en torno a Polaris.", "credito": "KPNO/NOIRLab/NSF/AURA", "licencia": "CC BY 4.0", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/kitt-peak-arcos.jpg"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'imagen', '{"tipo": "foto", "url": "https://cdn.eso.org/images/screen/171109-cc.jpg", "enlace": "https://www.eso.org/public/images/171109-cc/", "pie": "Hemisferio sur: fotografía de larga exposición con objetivo de ojo de pez en el observatorio Paranal (Chile). Los arcos giran en torno a otro punto del cielo, sin estrella brillante en el centro.", "credito": "ESO/A. Santerne", "licencia": "CC BY 4.0", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/paranal-arcos.jpg"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>Compruébalo tú mismo: fotografía el giro del cielo</h3>\n<p>Este es un hecho que puedes comprobar por tu cuenta, con una cámara y algo de paciencia.</p>\n<p><strong>Lo que necesitas.</strong> Una cámara o un móvil que permita fotos de exposición larga o en modo noche, un trípode o un apoyo que no se mueva, y una noche despejada lejos de las luces de la ciudad.</p>\n<p><strong>Hacia dónde apuntar en el hemisferio norte.</strong> Mira hacia el norte e inclina la cámara hacia arriba tantos grados como sea la latitud del lugar. En Madrid, a unos 40° de latitud, eso son unos 40°: algo menos de la mitad del camino entre el horizonte y el cenit, unos cuatro puños con el brazo estirado. Ahí está Polaris. Para encontrarla, busca la Osa Mayor, el conocido «carro»: las dos estrellas del extremo del carro señalan hacia Polaris, a unas cinco veces la distancia que hay entre ellas.</p>\n<p><strong>Hacia dónde apuntar en el hemisferio sur.</strong> Polaris no se ve: queda por debajo del horizonte. Mira hacia el sur e inclina la cámara tantos grados como sea la latitud del lugar; en Buenos Aires, unos 35°. El centro del giro, el polo sur celeste, no tiene estrella brillante. Para encontrarlo, prolonga el palo largo de la Cruz del Sur unas cuatro veces y media su longitud: llegarás muy cerca del polo.</p>\n<p><strong>Cerca del ecuador.</strong> Los dos polos celestes quedan casi a ras del horizonte, uno al norte y otro al sur. Mirando hacia el norte o hacia el sur verás arcos pegados al horizonte.</p>\n<p><strong>Si apuntas hacia arriba, al cenit.</strong> Desde España o desde Argentina también salen arcos, pero su centro queda fuera de la foto. Desde el ecuador, las estrellas del cenit trazan líneas casi rectas, de este a oeste.</p>\n<p><strong>Cómo hacer la foto.</strong> Hay dos maneras. Con una sola exposición muy larga, de 15 minutos a una hora, si la cámara lo permite. O con muchas fotos seguidas de 15 a 30 segundos cada una durante una o dos horas, que luego se suman en una sola con un programa de apilado gratuito, como StarStaX o Sequator; algunos móviles hacen esa suma por sí solos en su modo de estelas. Cuanto más tiempo, más largos serán los arcos.</p>\n<p><strong>Lo que vas a ver.</strong> Arcos de círculo con un centro común. Si mides la altura de ese centro sobre el horizonte, comprobarás que se parece a la latitud del lugar. Si alguien hace la misma foto a la vez desde el otro hemisferio, verá girar el cielo en sentido contrario alrededor del otro polo. El interactivo del apartado «El cielo como una cúpula», más arriba, te muestra hacia dónde apuntar desde cualquier latitud y cómo dibuja esa situación cada modelo.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que Polaris parece quieta porque está <strong>casi alineada con el eje de rotación de la Tierra</strong>. Según este modelo, la Tierra gira sobre ese eje una vez al día, y como Polaris queda prácticamente en su prolongación, se mantiene fija mientras el resto del cielo parece girar a su alrededor. Para este modelo, que la altura de Polaris cambie con la latitud es consecuencia de que la Tierra sea esférica: el ángulo de Polaris sobre el horizonte equivale a la latitud del observador.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 7, 'imagen', '{"tipo": "foto", "url": "https://images-assets.nasa.gov/image/as17-148-22727/as17-148-22727~medium.jpg", "enlace": "https://images.nasa.gov/details/as17-148-22727", "pie": "La NASA la publica como una fotografía tomada por la tripulación del Apolo 17 en 1972, de camino a la Luna. El modelo moderno la presenta entre sus pruebas; los defensores de la Tierra plana cuestionan la autenticidad de este tipo de imágenes.", "credito": "NASA", "licencia": "Dominio público", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/apolo17-as17-148-22727.jpg", "fecha": "1972"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 8, 'texto', '{"html": "<h3>Fotografía directa frente a composición: cómo leer una imagen de la Tierra</h3>\n<p>No todas las imágenes famosas de la Tierra vistas desde el espacio son fotografías en el mismo sentido. Conviene distinguir tres tipos: la <strong>fotografía directa</strong> (una sola toma de cámara), la <strong>composición de datos</strong> (muchas observaciones unidas por ordenador) y la <strong>ilustración o render</strong> (una recreación).</p>\n<p><strong>La foto del Apolo 17 (1972).</strong> Fue tomada el 7 de diciembre de 1972 por Ron Evans o Harrison Schmitt durante el viaje a la Luna, a unos 29.400 km de la superficie, con una cámara Hasselblad de 70 mm y objetivo de 80 mm. Su nombre oficial en el archivo de NASA es AS17-148-22727, y es la tercera de una serie de tomas casi idénticas hechas justo antes. Es una fotografía de una sola vez. Pero la versión que todos conocemos no es exactamente el original: se distribuyó recortada, girada para poner el sur abajo y con el color ajustado. En el fotograma original el polo sur aparece arriba, y la imagen abarca desde el Mediterráneo hasta la Antártida.</p>\n<p><strong>La «Blue Marble» de 2002.</strong> Pese al nombre, es otra cosa. Según la propia NASA, científicos y visualizadores unieron meses de observaciones de tierra, océanos, hielo marino y nubes en un mosaico continuo. La superficie procede de observaciones sin nubes tomadas entre junio y septiembre de 2001, el relieve se sombreó con datos de elevación del Servicio Geológico de EE. UU. y las nubes son una composición de dos días de imágenes. Su autor, Robert Simmon, explicó que renderizó por separado tierra y océano, brillos, nubes, máscaras de día y noche y la neblina atmosférica. Es decir: está hecha con datos reales, pero la imagen final es una construcción por ordenador, no una vista que alguien pudiera haber fotografiado.</p>\n<p><strong>Por qué importa.</strong> Llamar «foto real» a una composición es una afirmación sin matizar. La regla del curso es atribuir cada imagen a quien la produjo y decir cómo se hizo: quién, con qué instrumento, y si es una toma única, un montaje o una recreación.</p>\n<p class=\"fuentes\">Fuentes: <a href=\"https://en.wikipedia.org/wiki/The_Blue_Marble\" target=\"_blank\" rel=\"noopener\">Wikipedia, «The Blue Marble»</a> · <a href=\"https://earthobservatory.nasa.gov/Features/BlueMarble/BlueMarble_2002.php\" target=\"_blank\" rel=\"noopener\">NASA Earth Observatory, Blue Marble 2002</a> · <a href=\"https://svs.gsfc.nasa.gov/30614\" target=\"_blank\" rel=\"noopener\">NASA SVS, Blue Marble 2002</a> · <a href=\"https://earthobservatory.nasa.gov/blogs/elegantfigures/2011/10/\" target=\"_blank\" rel=\"noopener\">Robert Simmon, «Crafting the Blue Marble»</a></p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 9, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>El modelo terraplanista sostiene que Polaris es una estrella <strong>fija situada justo encima del Polo Norte</strong>, centro de un plano terrestre, y que las estrellas giran en círculo sobre ese plano como una cúpula que rota. En esta visión, los arcos circulares se explican por ese giro de la bóveda, no por el movimiento de la Tierra. Que Polaris baje en el cielo al viajar hacia el sur lo atribuyen a la <strong>perspectiva</strong>: igual que una farola parece más baja cuanto más te alejas de ella, la estrella se acercaría al horizonte a medida que el observador se aleja del centro.</p>\n<p><strong>El cielo del sur, un punto debatido.</strong> En el hemisferio sur las estrellas giran en sentido contrario alrededor de otro punto del cielo. La propia wiki de la Flat Earth Society reconoce que es un asunto muy discutido entre sus defensores, y recoge tres propuestas:</p>\n<ul><li><p><strong>Un solo centro, por perspectiva.</strong> Todo el cielo gira en torno al norte, pero quien mira hacia el sur ve las estrellas avanzar en sentido contrario, igual que algo que gira sobre nuestra cabeza parece girar al revés según hacia dónde miremos. En la wiki se atribuye a un colaborador que firma como P-Brane.</p></li><li><p><strong>Un solo centro, por efecto de cúpula.</strong> Dentro de la hipótesis de la «aceleración electromagnética», según la cual la luz se curva hacia arriba al recorrer grandes distancias, el cielo se vería como a través de una cúpula de cristal, y eso invertiría el giro aparente en el sur.</p></li><li><p><strong>Dos centros de giro.</strong> El modelo bipolar propone un segundo polo en el sur con su propio cielo giratorio encima. Exige un mapa distinto del de Gleason, con dos centros en lugar de uno.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 10, 'interactivo', '{"componente": "sur-plano", "etiqueta": "Interactivo", "modelo": "Según el modelo plano: tres propuestas", "pie": "Las tres propuestas que recoge la wiki de la Flat Earth Society para el giro del cielo del sur. Esquemas simplificados."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 11, 'imagen', '{"tipo": "obra", "url": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/gleason-1892-1400.jpg", "enlace": "https://collections.leventhalmap.org/search/commonwealth:7h149v85z", "pie": "Mapa del mundo de Alexander Gleason (1892), con el polo norte en el centro y el borde del sur alrededor. Es la disposición que suele usarse para representar el modelo plano de un solo centro. Amplíalo para leer sus anotaciones.", "credito": "Alexander Gleason, 1892. Leventhal Map & Education Center (Biblioteca Pública de Boston)", "licencia": "Sin restricciones de uso conocidas", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/gleason-1892.jpg", "fecha": "1892"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 12, 'texto', '{"html": "<h3>Un dato que cambia todo: la estrella polar no siempre fue Polaris</h3>\n<p>Un hecho observable a muy largo plazo, registrado desde la Antigüedad: el punto en torno al que giran las estrellas <strong>se desplaza lentamente</strong>. Hiparco lo notó comparando sus mediciones con otras más antiguas, y la astronomía moderna calcula que ese punto completa un gran círculo en unos 26.000 años. A esto se le llama <strong>precesión</strong>. Según ese cálculo, hacia el 2700 a. C. la estrella más cercana a ese punto era <strong>Thuban</strong>, en la constelación del Dragón; en tiempos de los griegos clásicos no había ninguna estrella brillante justo en el polo; Polaris alcanzará su máxima cercanía hacia el año 2100, y dentro de unos 12.000 años el papel lo tendrá <strong>Vega</strong>. Esto importa porque cada cultura vio un cielo polar distinto, y cualquier explicación del cielo, sea cual sea su modelo, tiene que dar cuenta también de este lento desplazamiento.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 13, 'interactivo', '{"componente": "precesion", "etiqueta": "Interactivo", "modelo": "Observación, con el cálculo moderno de la precesión", "pie": "Mueve el año y observa cómo el polo celeste pasa de Thuban a Polaris y a Vega."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 14, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> Concebían el universo como <strong>An</strong> (el cielo) sobre <strong>Ki</strong> (la tierra). En las tablillas astronómicas babilónicas conocidas como MUL.APIN (compiladas hacia el 1000 a. C.), el cielo se divide en tres franjas o \"caminos\": el de Anu en el centro, el de Enlil al norte y el de Ea al sur. Las estrellas que giran cerca del polo pertenecían al camino de Enlil.</p>\n<p><strong>Egipcios.</strong> Imaginaban el cielo como el cuerpo de la diosa <strong>Nut</strong>, arqueado sobre la tierra. Llamaban a las estrellas circumpolares, las que nunca se ponen, <em>ikhemu-sek</em>, \"las que no conocen la destrucción\" o \"imperecederas\", y aparecen en los Textos de las Pirámides. En su época la estrella polar era Thuban; algunos investigadores han propuesto que un conducto de la Gran Pirámide apuntaba hacia la región polar, aunque es una interpretación debatida.</p>\n<p><strong>Griegos.</strong> Concibieron una <strong>esfera celeste</strong> que gira en torno a un eje fijo, con la Tierra en el centro. Aristóteles, en <em>Sobre el cielo</em>, usó precisamente este fenómeno como argumento: al viajar al norte o al sur cambian las estrellas visibles, lo que para él indicaba una Tierra esférica y no muy grande. Hiparco, hacia el 130 a. C., fue quien detectó la precesión comparando sus mediciones con otras más antiguas.</p>\n<p><strong>Romanos y el mundo grecorromano.</strong> Heredaron y sistematizaron el modelo griego. Ptolomeo, en el <em>Almagesto</em> (siglo II d. C., en Alejandría), fijó el modelo geocéntrico de esferas que dominaría unos catorce siglos. Autores latinos como Cicerón (<em>El sueño de Escipión</em>) describieron el cosmos como nueve esferas encajadas, con la de las estrellas fijas girando por fuera.</p>\n<p><strong>Cosmología bíblica y rabínica.</strong> El Génesis describe un <strong>firmamento</strong> (<em>raqia</em>) que separa las aguas de arriba de las de abajo, y en el que se colocan el Sol, la Luna y las estrellas. La tradición rabínica hablaba de varios cielos superpuestos, a menudo siete. El Talmud (Pesajim 94b) recoge un debate notable: los sabios de Israel sostenían que de noche el Sol pasaba por encima del firmamento, y los sabios de otras naciones que pasaba por debajo de la tierra; el propio Rabí Yehudá HaNasí concedió que la segunda postura parecía más acertada.</p>\n<p><strong>Libro de Enoc.</strong> El llamado <em>1 Enoc</em> es una colección de textos judíos antiguos; se conserva completo en ge''ez (etiópico), es canónico en la Iglesia ortodoxa etíope Tewahedo, y en Qumrán se hallaron fragmentos en arameo. La Epístola de Judas (versículos 14-15) cita un pasaje suyo. Su parte astronómica, el <em>Libro de las Luminarias</em> (capítulos 72-82), está considerada por los especialistas entre las secciones más antiguas, quizá del siglo III a. C. En él, el ángel Uriel muestra a Enoc las leyes de los astros. En el <em>Libro de los Vigilantes</em> (capítulos 33-36) Enoc viaja a los confines de la tierra y ve las <strong>puertas del cielo</strong> por donde salen las estrellas, y en el norte otras puertas de las que salen los vientos. Es decir, un cielo con límites, aberturas y salidas fijas, donde cada astro tiene su puerta y su orden.</p>\n<p><strong>Cábala.</strong> Su texto central, el <em>Zóhar</em> (difundido en Castilla a finales del siglo XIII), contiene un pasaje atribuido a Rav Hamnuná Saba según el cual la tierra gira como una esfera, de modo que cuando es de día para unos es de noche para otros. Es un ejemplo de cómo dentro de una misma tradición conviven modelos distintos del cielo.</p>\n<p><strong>Cristianismo medieval.</strong> La visión dominante, la de Tomás de Aquino o la que retrata Dante, adoptó el cosmos de Aristóteles y Ptolomeo: la Tierra esférica en el centro, rodeada por las esferas de la Luna, Mercurio, Venus, el Sol, Marte, Júpiter, Saturno y las estrellas fijas, luego el <em>primer móvil</em>, que imprime el giro diario a todo, y por fin el <strong>Empíreo</strong>. El manual universitario de astronomía más usado, <em>De sphaera</em> de Sacrobosco (siglo XIII), enseñaba la Tierra esférica. Hubo voces minoritarias distintas, como Cosmas Indicopleustes (siglo VI), que describió un mundo con forma de tabernáculo bajo una bóveda.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 15, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/Cellarius_Harmonia_Macrocosmica_-_Scenographia_Systematis_mundani_Ptolemaici.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:Cellarius_Harmonia_Macrocosmica_-_Scenographia_Systematis_mundani_Ptolemaici.jpg", "pie": "El sistema de Ptolomeo en el atlas «Harmonia Macrocosmica» de Andreas Cellarius (1660): la Tierra en el centro, rodeada por las esferas de los astros.", "credito": "Andreas Cellarius", "licencia": "Dominio público", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/cellarius-ptolomeo.jpg", "fecha": "1660"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 16, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/Flammarion.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:Flammarion.jpg", "pie": "Grabado publicado por Camille Flammarion en «L''atmosphère» (París, 1888): un viajero asoma la cabeza más allá de la bóveda del cielo. Aunque a menudo se presenta como medieval, es del siglo XIX.", "credito": "Autor desconocido, en C. Flammarion, 1888", "licencia": "Dominio público", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/flammarion.jpg", "fecha": "1888"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 17, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/WorldMapCosmasIndicopleustes.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:WorldMapCosmasIndicopleustes.jpg", "pie": "Mapa del mundo de la «Topografía cristiana» de Cosmas Indicopleustes (siglo VI), tal como se conserva en copias manuscritas: la tierra habitada rodeada por el océano.", "credito": "Cosmas Indicopleustes (copia manuscrita)", "licencia": "Dominio público", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/cosmas.jpg", "fecha": "Siglo VI"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 18, 'texto', '{"html": "<h3>Lo que cada modelo le pregunta al otro</h3>\n<p>Las dos explicaciones parten del mismo hecho — los arcos en torno a Polaris — y cada una lo explica con su propia lógica. Entre sus defensores hay preguntas cruzadas que cada parte considera decisivas. Aquí se recogen tal como las plantea cada una, junto con la respuesta que da la otra, para que puedas valorarlas tú.</p>\n<p><strong>Lo que los defensores de la Tierra plana preguntan al modelo moderno.</strong></p>\n<ul><li><p><em>¿Por qué no sentimos que la Tierra gira?</em> Según el modelo moderno, en el ecuador la superficie se movería a unos 1.670 km/h. Su respuesta es que un movimiento constante no se percibe, igual que no se nota la velocidad dentro de un avión en vuelo estable; solo se notan los cambios de velocidad.</p></li><li><p><em>¿Por qué el horizonte se ve plano y siempre a la altura de los ojos?</em> El modelo moderno responde que, con el tamaño que atribuye a la Tierra, la curvatura es muy suave a escala humana, y que el descenso del horizonte existe pero es pequeño y se mide con instrumentos desde lugares altos.</p></li><li><p><em>¿Por qué a veces se ven costas o edificios muy lejanos que la curvatura debería ocultar?</em> El modelo moderno lo atribuye a la refracción atmosférica, que curva la luz cerca del suelo y cambia con la temperatura del aire.</p></li></ul>\n<p><strong>Lo que los defensores del modelo moderno preguntan al modelo plano.</strong></p>\n<ul><li><p><em>¿Qué pasa en el hemisferio sur?</em> Allí Polaris no se ve, y las estrellas giran en torno a otro punto, en sentido contrario. Dentro del modelo plano hay tres propuestas, explicadas más arriba en su apartado, y sus defensores no coinciden en una sola.</p></li><li><p><em>¿Por qué los barcos que se alejan desaparecen empezando por el casco?</em> Muchos defensores del modelo plano lo atribuyen a la perspectiva y a la refracción, y afirman que con un buen zoom el barco vuelve a verse entero.</p></li><li><p><em>¿Cómo se explican los eclipses de Luna?</em> Se trata en su propio apartado, más abajo.</p></li></ul>\n<p>La capa avanzada del módulo recogerá las fuentes de cada postura y los experimentos que cada parte propone.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 5;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 6, 'el-sol-las-estaciones-y-la-ecliptica', 'El Sol, las estaciones y la eclíptica' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>El Sol no sale siempre por el mismo punto: a lo largo del año su salida se desplaza por el horizonte, hacia el norte hasta el <strong>solsticio de verano</strong> y hacia el sur hasta el <strong>solsticio de invierno</strong>. En los <strong>equinoccios</strong> sale casi exactamente por el este.</p></li><li><p>Su altura a mediodía y la duración del día cambian con las estaciones.</p></li><li><p>Las constelaciones visibles de noche cambian a lo largo del año. Todas las tradiciones dedujeron de ello que el Sol recorre lentamente un camino entre las estrellas, siempre el mismo: la <strong>eclíptica</strong>.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que la Tierra da una vuelta al Sol cada año con su eje inclinado unos 23,4°. Esa inclinación hace que cada hemisferio reciba la luz más directa en una mitad del año: de ahí las estaciones. La eclíptica es la proyección en el cielo del plano de la órbita terrestre.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>El modelo terraplanista sostiene que el Sol es mucho más pequeño y cercano, y gira en círculo por encima del plano terrestre. A lo largo del año ese círculo se estrecha y se ensancha: en junio recorre una órbita interior (sobre el trópico de Cáncer) y en diciembre una exterior (sobre el de Capricornio). Su luz funcionaría como un foco que ilumina solo una zona, lo que explicaría el día, la noche y las estaciones.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'interactivo', '{"componente": "sol-dos-modelos", "etiqueta": "Interactivo", "modelo": "Dos modelos: moderno y plano", "pie": "El mismo año explicado por los dos modelos. Arriba, la Tierra inclinada alrededor del Sol; abajo, el Sol girando sobre el plano entre los trópicos. Esquemas, no a escala."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> El Sol era el dios Utu (Shamash en acadio). En los sellos cilíndricos aparece saliendo entre dos montañas por una puerta del este. Las tablillas MUL.APIN ya registran los solsticios y equinoccios y la duración cambiante de los días.</p>\n<p><strong>Egipcios.</strong> El Sol, Ra, recorría de día el cuerpo de Nut en una barca; al atardecer Nut lo engullía y de noche atravesaba la <strong>Duat</strong>, el mundo inferior, para renacer al amanecer. Así lo muestra el texto llamado <em>Libro de Nut</em> (o <em>Fundamentos del curso de las estrellas</em>).</p>\n<p><strong>Griegos.</strong> El Sol iba en su propia esfera, inclinada respecto al ecuador celeste: los griegos midieron esa inclinación de la eclíptica. Eratóstenes, hacia el 240 a. C., comparó la sombra del Sol en Siena y en Alejandría el mismo día y, suponiendo una Tierra esférica y un Sol lejano, calculó la circunferencia terrestre.</p>\n<p><strong>Romanos y Ptolomeo.</strong> En el <em>Almagesto</em>, el Sol ocupa la cuarta esfera contando desde la Tierra, y su movimiento algo desigual a lo largo del año se explica con un círculo desplazado del centro.</p>\n<p><strong>Cosmología bíblica.</strong> El Salmo 19 describe al Sol saliendo como un esposo de su tálamo y recorriendo el cielo de un extremo a otro. El Eclesiastés (1:5) dice que el Sol sale, se pone y vuelve presuroso a su lugar para salir de nuevo. En Josué 10 el Sol se detiene sobre Gabaón.</p>\n<p><strong>Libro de Enoc.</strong> Es el texto antiguo que describe el recorrido solar con más detalle (capítulo 72). El cielo tiene <strong>seis puertas al este y seis al oeste</strong>. El Sol sale por una puerta distinta según la época del año y avanza de puerta en puerta, mes a mes. El día y la noche se miden en dieciocho partes que se reparten de forma distinta según la puerta: en el día más largo, doce partes de día y seis de noche. De noche, dice el texto, el Sol regresa <strong>por el norte</strong> para volver a salir por el este. El año resultante es de <strong>364 días</strong>, exactamente 52 semanas, y el libro defiende ese calendario frente a otros.</p>\n<p><strong>Cristianismo medieval.</strong> Siguió el modelo de Ptolomeo: el Sol en la cuarta esfera, movido por la esfera superior. El <em>De sphaera</em> de Sacrobosco explicaba las estaciones por la inclinación de la eclíptica sobre una Tierra esférica e inmóvil.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/Cellarius_Harmonia_Macrocosmica_-_Solis_circa_Orbem_Terrarum_Spiralis_Revolutio.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:Cellarius_Harmonia_Macrocosmica_-_Solis_circa_Orbem_Terrarum_Spiralis_Revolutio.jpg", "pie": "Cellarius (1660): el recorrido en espiral del Sol alrededor de la Tierra a lo largo del año, según el modelo geocéntrico.", "credito": "Andreas Cellarius", "licencia": "Dominio público", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/cellarius-espiral.jpg", "fecha": "1660"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 7, 'interactivo', '{"componente": "puertas-enoc", "etiqueta": "Interactivo", "modelo": "Según el Libro de Enoc", "pie": "Libro de Enoc, cap. 72: el Sol sale cada mes por una de las seis puertas del este."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 6;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 7, 'la-luna-y-sus-fases', 'La Luna y sus fases' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>La Luna pasa de creciente a llena y de menguante a nueva en unos <strong>29,5 días</strong>.</p></li><li><p>Siempre muestra la misma cara.</p></li><li><p>La parte iluminada siempre mira hacia donde está el Sol.</p></li><li><p>Cada día sale, de media, unos 50 minutos más tarde que el anterior.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'interactivo', '{"componente": "fases-luna", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "Arrastra para recorrer un mes lunar de unos 29,5 días. El botón muestra, además, el esquema con el que lo explica el modelo moderno."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'imagen', '{"tipo": "foto", "url": "https://cdn.eso.org/images/screen/eso1210a.jpg", "enlace": "https://www.eso.org/public/images/eso1210a/", "pie": "Luna creciente sobre el observatorio Paranal (Chile), el 27 de octubre de 2011. La parte oscura brilla débilmente: es la llamada luz cenicienta.", "credito": "ESO/B. Tafreshi (twanight.org)", "licencia": "CC BY 4.0", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/paranal-luna.jpg", "fecha": "2011"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que la Luna no tiene luz propia: refleja la del Sol mientras gira alrededor de la Tierra. Según el ángulo entre Sol, Tierra y Luna vemos más o menos de su mitad iluminada, y eso son las fases. Muestra siempre la misma cara porque tarda lo mismo en girar sobre sí misma que en dar la vuelta a la Tierra.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>En el modelo terraplanista la Luna, como el Sol, es un astro pequeño y cercano que gira sobre el plano. Sobre su luz y sus fases hay dos posturas:</p>\n<ul><li><p><strong>Luz propia.</strong> Samuel Rowbotham, en <em>Zetetic Astronomy: Earth Not a Globe</em> (1881), sostuvo que la Luna brilla con luz propia y es semitransparente. Argumentaba que su luz tiene un carácter distinto del de la luz solar y que una esfera que solo reflejara la luz del Sol no podría verse iluminada por igual en toda su cara.</p></li><li><p><strong>Luz del Sol con rayos curvos.</strong> La wiki de la Flat Earth Society propone que la Luna sí recibe la luz del Sol, pero que esos rayos se curvan hacia arriba (la «aceleración electromagnética»). Las fases dependerían de la posición y la altura de la Luna respecto al Sol: llena cuando está lejos del Sol y más alta, nueva cuando está cerca y más baja. La propia wiki admite que no se conoce el mecanismo que curvaría la luz.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> La Luna era el dios Nanna (Sin en acadio). Su calendario era lunar: el mes empezaba con la primera observación de la Luna creciente tras la puesta del Sol. Las tablillas MUL.APIN enumeran las constelaciones \"en el camino de la Luna\".</p>\n<p><strong>Egipcios.</strong> La Luna se asociaba a los dioses Thot y Jonsu. Junto a su calendario civil de 365 días, usaban un calendario lunar para las fiestas religiosas.</p>\n<p><strong>Griegos.</strong> Anaxágoras (siglo V a. C.) sostuvo que la Luna recibe su luz del Sol. Aristarco de Samos (siglo III a. C.) usó la media luna para intentar calcular las distancias relativas de la Luna y el Sol.</p>\n<p><strong>Romanos y Ptolomeo.</strong> La Luna ocupa la esfera más cercana a la Tierra. Esa esfera marcaba una frontera: por debajo, el mundo cambiante; por encima, el cielo incorruptible.</p>\n<p><strong>Cosmología bíblica y rabínica.</strong> El Génesis (1:16) habla de dos grandes lumbreras, la mayor para el día y la menor para la noche, y el Salmo 104 dice que la Luna se hizo para marcar los tiempos. El calendario hebreo es lunisolar: meses lunares ajustados al año solar añadiendo un mes extra en algunos años.</p>\n<p><strong>Libro de Enoc.</strong> Los capítulos 73-74 tratan de la Luna. Su círculo es como el del Sol, entra y sale por las mismas puertas, y su luz crece en una séptima parte cada vez y luego mengua del mismo modo. El texto compara el año lunar de <strong>354 días</strong> con su año solar de 364 y explica la diferencia que se acumula entre ambos.</p>\n<p><strong>Cristianismo medieval.</strong> Mantuvo el modelo aristotélico: la esfera de la Luna separaba el mundo terrenal, sujeto a cambio y corrupción, del mundo celeste, perfecto e inmutable.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 7;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 8, 'los-eclipses', 'Los eclipses' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>Los <strong>eclipses de Sol</strong> solo ocurren en luna nueva, y los <strong>de Luna</strong> solo en luna llena. Pero no hay eclipse cada mes.</p></li><li><p>Se repiten siguiendo ciclos regulares; el más conocido, el <strong>saros</strong>, dura unos 18 años y 11 días.</p></li><li><p>Un eclipse total de Sol solo se ve en una franja estrecha de terreno; uno de Luna se ve a la vez desde toda la mitad nocturna del mundo.</p></li><li><p>En un eclipse total de Luna, esta no desaparece: se vuelve rojiza.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>Los tipos de eclipse</h3>\n<p><strong>De Sol:</strong></p>\n<ul><li><p><strong>Total</strong>: el disco solar queda tapado por completo durante unos instantes (la fase de totalidad) y se ve la corona.</p></li><li><p><strong>Parcial</strong>: solo se tapa una parte.</p></li><li><p><strong>Anular</strong>: se tapa el centro pero queda un anillo de Sol visible.</p></li><li><p><strong>Híbrido</strong>: total en unos lugares y anular en otros, a lo largo de la misma franja.</p></li></ul>\n<p><strong>De Luna:</strong></p>\n<ul><li><p><strong>Total</strong>: la Luna entera se oscurece y enrojece.</p></li><li><p><strong>Parcial</strong>: solo una parte entra en la sombra oscura.</p></li><li><p><strong>Penumbral</strong>: la Luna apenas se oscurece levemente, a menudo sin que se note a simple vista.</p></li><li><p><strong>Penumbral total</strong>: la Luna entra por completo en la penumbra, pero sin llegar a tocar la sombra oscura; es poco frecuente y de oscurecimiento sutil.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'interactivo', '{"componente": "tipos-eclipse", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "Cómo se ve cada tipo de eclipse desde el suelo. Esquema, no a escala."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'imagen', '{"tipo": "foto", "url": "https://www.nasa.gov/wp-content/uploads/2023/03/36329608000_2e0f627e4b_o.jpg", "enlace": "https://www.nasa.gov/image-article/suns-corona-seen-during-2017-solar-eclipse/", "pie": "Eclipse total de Sol del 21 de agosto de 2017, fotografiado desde un avión sobre Oregón (Estados Unidos): durante la totalidad se ve la corona.", "credito": "NASA/Carla Thomas", "licencia": "Dominio público", "fecha": "2017"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'imagen', '{"tipo": "foto", "url": "https://cdn.eso.org/images/screen/potw2221a.jpg", "enlace": "https://www.eso.org/public/images/potw2221a/", "pie": "Eclipse total de Luna del 15 de mayo de 2022, visto desde el observatorio Paranal (Chile): durante la totalidad la Luna toma un tono rojizo.", "credito": "F. Aedo, F. Durán/ESO", "licencia": "CC BY 4.0", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/paranal-eclipse-luna.jpg", "fecha": "2022"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que un eclipse de Sol ocurre cuando la Luna se interpone entre el Sol y la Tierra, y uno de Luna cuando la Tierra se interpone y proyecta su sombra sobre ella. No ocurren cada mes porque la órbita lunar está inclinada unos 5° respecto a la eclíptica, y solo se alinean los tres en ciertas épocas. El eclipse anular se da cuando la Luna está en la parte más lejana de su órbita y se ve algo más pequeña que el Sol. El color rojo de la Luna se atribuye a la luz solar que atraviesa la atmósfera terrestre y se curva hacia ella.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 7, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>Para los eclipses de Sol, muchos defensores aceptan que es la Luna la que pasa por delante. Para los de Luna no recurren a la sombra de la Tierra, porque en su modelo la Tierra no se interpone entre el Sol y la Luna. Hay dos propuestas principales:</p>\n<ul><li><p><strong>Un cuerpo oscuro y semitransparente.</strong> Rowbotham (1881) rechazó la sombra de la Tierra y propuso que entre la Luna y el observador pasa un cuerpo no luminoso y semitransparente, quizá un satélite oscuro. Como apoyo citaba que durante la totalidad la Luna puede verse rojiza o incluso brillante, algo que, a su juicio, una simple sombra no explicaría.</p></li><li><p><strong>El «objeto de sombra».</strong> La wiki de la Flat Earth Society habla de un objeto no visto que orbita cerca del Sol y que, al pasar entre el Sol y la Luna, proyecta su sombra sobre ella. Le atribuye una inclinación de unos 5° y deja abierto que pudiera ser un cuerpo ya conocido; no precisa su tamaño ni su naturaleza.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 8, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> Fueron los grandes registradores de eclipses. Durante siglos los anotaron en los llamados <em>Diarios astronómicos</em> y en la serie <em>Enuma Anu Enlil</em>, y a partir de esas listas descubrieron que se repetían en ciclos, lo que les permitió predecir los eclipses de Luna.</p>\n<p><strong>Egipcios.</strong> Sorprendentemente, se han conservado muy pocos registros egipcios claros de eclipses, pese a su observación del cielo.</p>\n<p><strong>Griegos.</strong> Heródoto cuenta que Tales de Mileto predijo un eclipse de Sol (habitualmente fechado en el 585 a. C.), aunque los historiadores discuten cómo pudo hacerlo. Aristóteles usó los eclipses de Luna como argumento: la sombra de la Tierra sobre la Luna es siempre curva, lo que para él probaba una Tierra esférica. El <strong>mecanismo de Anticitera</strong> (siglos II-I a. C.), hallado en un naufragio, es un artefacto de engranajes que calculaba ciclos de eclipses.</p>\n<p><strong>Romanos y Ptolomeo.</strong> El <em>Almagesto</em> dedica capítulos enteros al cálculo de eclipses, apoyándose en registros babilónicos antiguos.</p>\n<p><strong>Cosmología bíblica y rabínica.</strong> El libro de Joel (2:31) habla del Sol convertido en tinieblas y la Luna en sangre, una imagen que muchos lectores relacionan con los eclipses. El Talmud (Sucot 29a) trata de los eclipses, pero en clave de significado, que corresponde al módulo 8.</p>\n<p><strong>Libro de Enoc.</strong> En los textos conservados del <em>Libro de las Luminarias</em> no aparece una descripción explícita de los eclipses. Su cielo de puertas y recorridos ordenados se centra en la regularidad de los astros, no en estas excepciones.</p>\n<p><strong>Cristianismo medieval.</strong> Heredó de Ptolomeo el cálculo de eclipses. Un debate famoso giró en torno a la oscuridad que, según los Evangelios, cubrió la tierra en la crucifixión: autores como Orígenes ya observaron que no pudo ser un eclipse solar normal, porque la Pascua judía cae en luna llena, y un eclipse de Sol solo ocurre en luna nueva.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 8;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 9, 'los-planetas-los-astros-errantes', 'Los planetas: los astros errantes' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>A simple vista se ven cinco \"estrellas\" que no siguen al resto: <strong>Mercurio, Venus, Marte, Júpiter y Saturno</strong>. La palabra <em>planeta</em> viene del griego y significa \"errante\".</p></li><li><p>Se mueven siempre cerca de la eclíptica, el mismo camino que el Sol y la Luna.</p></li><li><p>De vez en cuando parecen frenar, retroceder y volver a avanzar: es el <strong>movimiento retrógrado</strong>.</p></li><li><p>Mercurio y Venus nunca se alejan mucho del Sol: se ven al amanecer o al anochecer, de ahí el \"lucero del alba\" y el \"lucero vespertino\".</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 9;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que los planetas, incluida la Tierra, giran alrededor del Sol. El retroceso aparente se debe a la perspectiva: cuando la Tierra adelanta a un planeta más lento, este parece ir hacia atrás, como un coche que adelantamos en la autopista. Mercurio y Venus siempre están cerca del Sol porque sus órbitas son interiores a la nuestra. Este modelo se fue construyendo con Copérnico (1543), Kepler, que propuso órbitas elípticas (1609), y Galileo, que con el telescopio vio las lunas de Júpiter y las fases de Venus (1610).</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 9;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'animacion', '{"componente": "retrogrado", "etiqueta": "Animación", "modelo": "Tres modelos comparados", "pie": "Un mismo bucle de Marte con tres disposiciones: la heliocéntrica de Copérnico y Kepler, la geocéntrica de Ptolomeo con epiciclos y la de la Flat Earth Society, con los planetas girando alrededor de un Sol que da vueltas sobre el centro del plano. Esquemas simplificados."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 9;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>El modelo terraplanista suele considerar los planetas como luminarias errantes en el firmamento, no como mundos. Para el movimiento retrógrado, la wiki de la Flat Earth Society propone que los planetas giran alrededor del Sol y que el Sol, a su vez, da vueltas sobre el centro del plano: la suma de los dos giros haría que, vistos desde la Tierra, algunos planetas dibujen bucles hacia atrás. Es una disposición parecida a la que propuso Tycho Brahe en 1588 para un mundo con la Tierra quieta en el centro.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 9;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> Asociaban cada planeta a una divinidad: Júpiter a Marduk, Venus a Ishtar, Marte a Nergal. Siguieron sus movimientos durante siglos y desarrollaron esquemas aritméticos para predecir sus posiciones, incluidos los retrocesos. La llamada <em>Tablilla de Venus de Ammisaduqa</em> registra las apariciones y desapariciones de Venus.</p>\n<p><strong>Egipcios.</strong> Conocían los cinco planetas visibles y los representaban como dioses navegando por el cielo; varios llevaban nombres relacionados con Horus.</p>\n<p><strong>Griegos.</strong> Eudoxo (siglo IV a. C.) explicó los movimientos planetarios con esferas encajadas que giraban sobre ejes distintos. Aristarco de Samos (siglo III a. C.) propuso ya un modelo con el Sol en el centro, que no fue aceptado en su tiempo.</p>\n<p><strong>Romanos y Ptolomeo.</strong> El <em>Almagesto</em> explica el retroceso con los <strong>epiciclos</strong>: cada planeta gira en un círculo pequeño cuyo centro, a su vez, recorre un círculo grande alrededor de la Tierra. Este modelo predecía las posiciones con notable precisión y se usó durante unos catorce siglos.</p>\n<p><strong>Cosmología bíblica.</strong> La Biblia apenas distingue los planetas de las estrellas. Isaías 14:12 menciona al \"lucero, hijo de la aurora\", que suele identificarse con Venus.</p>\n<p><strong>Libro de Enoc.</strong> En el <em>Libro de los Vigilantes</em> (capítulos 18 y 21), Enoc ve siete estrellas castigadas \"porque no salieron a su tiempo\". Algunos estudiosos han propuesto que se refiere a los planetas, cuyo movimiento irregular no encaja en el orden de las demás estrellas. Es una interpretación, no algo que el texto diga expresamente.</p>\n<p><strong>Cristianismo medieval.</strong> Cada planeta tenía su esfera, y teólogos como Tomás de Aquino discutieron si esas esferas eran movidas por inteligencias o ángeles. En la <em>Divina Comedia</em>, Dante asciende de esfera en esfera, de la Luna a Saturno.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 9;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 10, 'el-zodiaco-y-las-constelaciones', 'El zodiaco y las constelaciones' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<h3>Lo que se observa</h3>\n<ul><li><p>Las estrellas forman grupos reconocibles que mantienen su forma a lo largo de toda una vida humana: las <strong>constelaciones</strong>.</p></li><li><p>El Sol, la Luna y los planetas recorren siempre la misma franja de constelaciones: el <strong>zodiaco</strong>.</p></li><li><p>Por la precesión (ver el apartado de Polaris), el punto donde está el Sol en el equinoccio de primavera se desplaza lentamente por el zodiaco. Hace unos dos mil años estaba en Aries; hoy está en Piscis, acercándose a Acuario.</p></li></ul>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 10;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>La explicación moderna</h3>\n<p>La astronomía moderna sostiene que las estrellas de una constelación suelen estar a distancias muy distintas de nosotros y solo parecen agrupadas desde la Tierra. La Unión Astronómica Internacional reconoce oficialmente <strong>88 constelaciones</strong>, con fronteras fijadas en 1930, y según esas fronteras la eclíptica atraviesa trece, porque también cruza Ofiuco.</p>\n<p>Aquí conviven dos sistemas que conviene no confundir. Las <strong>constelaciones</strong> son grupos de estrellas de tamaños desiguales. Los <strong>signos</strong> de la astrología occidental son doce partes iguales de 30° que empiezan en el equinoccio de primavera: es el llamado <strong>zodiaco tropical</strong>, ligado a las estaciones y no a las estrellas, así que con la precesión los signos y las constelaciones del mismo nombre se han ido separando. La astrología védica usa en cambio un <strong>zodiaco sideral</strong>, que sigue a las estrellas. Cada sistema mide una cosa distinta; el módulo 7 lo verá con detalle.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 10;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'interactivo', '{"componente": "zodiaco", "etiqueta": "Interactivo", "modelo": "Constelaciones y signos", "pie": "Fuera, las constelaciones por las que pasa el Sol; dentro, los doce signos del zodiaco tropical, que empiezan en el equinoccio. Mueve el año para ver cómo se separan."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 10;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'texto', '{"html": "<h3>La explicación terraplanista</h3>\n<p>En el modelo terraplanista las estrellas son luces situadas en la cúpula o firmamento, a no mucha distancia, y las constelaciones son figuras de esa misma bóveda que gira en torno al polo.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 10;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'texto', '{"html": "<h3>Cómo lo entendían otras cosmovisiones</h3>\n<p><strong>Sumerios y babilonios.</strong> Muchas de nuestras constelaciones vienen de ellos. Las tablillas MUL.APIN enumeran unas diecisiete constelaciones \"en el camino de la Luna\", y hacia el siglo V a. C. los astrónomos babilónicos fijaron el zodiaco de doce signos iguales.</p>\n<p><strong>Egipcios.</strong> Usaban los <strong>decanos</strong>: 36 grupos de estrellas que salían sucesivamente, cada uno durante unos diez días, y que servían para medir las horas de la noche. El famoso <strong>zodiaco de Dendera</strong> es ya de época ptolemaica (hacia el 50 a. C.) y combina los decanos egipcios con los signos babilónicos y griegos.</p>\n<p><strong>Griegos.</strong> Recibieron el zodiaco de Babilonia y le dieron sus mitos. El poema <em>Fenómenos</em> de Arato describe las constelaciones, y Ptolomeo cataloga 48 en el <em>Almagesto</em>, base de las que usamos hoy.</p>\n<p><strong>Romanos.</strong> Poetas como Manilio, en su <em>Astronómica</em> (siglo I d. C.), divulgaron en latín el zodiaco y las constelaciones.</p>\n<p><strong>Cosmología bíblica y rabínica.</strong> El libro de Job (9:9 y 38:31-32) nombra las Pléyades, Orión, la Osa y las <em>Mazzaroth</em>, palabra que muchos traducen como las constelaciones o el zodiaco. En sinagogas antiguas de Galilea, como la de Hamat Tiberias (siglo IV) y la de Beit Alfa (siglo VI), se han hallado mosaicos con la rueda del zodiaco.</p>\n<p><strong>Cábala.</strong> El <em>Séfer Yetzirá</em>, uno de sus textos fundacionales, organiza el cosmos en correspondencias: doce letras del alfabeto hebreo para los doce signos, siete para los siete planetas. Aquí solo se señala esa estructura; su significado se verá en el módulo 8.</p>\n<p><strong>Libro de Enoc.</strong> El <em>Libro de las Luminarias</em> describe estrellas con \"jefes\" que las guían en su orden y en sus meses, y doce puertas en los confines del cielo. Todo el cielo aparece como un sistema ordenado de puertas, guardianes y turnos, que Uriel enseña a Enoc.</p>\n<p><strong>Cristianismo medieval.</strong> El zodiaco se integró en el calendario: en catedrales como Chartres o Amiens se esculpieron los signos junto a los trabajos de cada mes.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 10;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'imagen', '{"tipo": "obra", "url": "https://commons.wikimedia.org/wiki/Special:FilePath/Description_of_Egypt._2nd_edition._1822._Vol._4._Pl._21_%28Dendera_Circular_Zodiac%29.jpg?width=1280", "enlace": "https://commons.wikimedia.org/wiki/File:Description_of_Egypt._2nd_edition._1822._Vol._4._Pl._21_%28Dendera_Circular_Zodiac%29.jpg", "pie": "El zodiaco circular de Dendera dibujado para la «Description de l''Égypte» (edición de 1822). El original, un relieve de época ptolemaica, se conserva hoy en el Museo del Louvre.", "credito": "Description de l''Égypte", "licencia": "Dominio público", "grande": "https://gjkvcdkidjxenhfgxvkc.supabase.co/storage/v1/object/public/medios/modulo-1/grande/dendera.jpg", "fecha": "1822"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 10;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 11, 'orientarse-en-el-cielo', 'Orientarse en el cielo' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>Todo lo anterior sirve para entender el cielo. Esta sección sirve para salir una noche y encontrar lo que buscas: saber qué hay sobre tu cabeza, ir de una estrella a otra y saber dónde está el norte sin brújula.</p>\n<p>Las técnicas que siguen se basan solo en lo que se observa. Por eso funcionan igual sea cual sea el modelo del mundo de quien las usa, y las han usado navegantes, pastores y viajeros de todas las culturas.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>El cielo de esta noche</h3>\n<p>El mapa interactivo de este apartado muestra el cielo de cualquier fecha, hora y lugar, y por defecto el de ahora mismo. Funciona como los planisferios giratorios de cartón que usan los aficionados: es el cielo visto como una cúpula sobre tu cabeza.</p>\n<ul><li><p><strong>El centro del mapa es el cenit</strong>, el punto que tienes justo encima, y <strong>el borde es el horizonte</strong>. Cuanto más cerca del borde está una estrella, más baja la verás.</p></li><li><p><strong>La dirección hacia la que miras va abajo.</strong> Elige con los botones si miras al norte, al sur, al este o al oeste, y sujeta el móvil por encima de tu cabeza con esa dirección hacia abajo: así el mapa coincide con el cielo. Por eso el este y el oeste parecen cambiados respecto a un mapa de la Tierra: un mapa del cielo se mira desde abajo.</p></li><li><p><strong>La línea dorada discontinua es la eclíptica</strong>, el camino del Sol entre las estrellas. La Luna y los planetas siempre andan cerca de ella.</p></li><li><p><strong>Los planetas</strong> aparecen con su nombre y su color. A simple vista se distinguen de las estrellas porque suelen centellear menos y, con los días, cambian de sitio respecto a ellas.</p></li></ul>\n<p>Toca cualquier estrella con nombre, un planeta o la Luna, y el mapa te dirá hacia qué punto cardinal mirar y cuántos puños levantar la vista.</p>\n<p><strong>Consejos para observar.</strong> Busca un lugar lejos de las farolas. Deja que tus ojos se acostumbren a la oscuridad durante unos veinte minutos sin mirar pantallas brillantes; si usas el móvil, baja el brillo al mínimo. La Luna llena ilumina tanto el cielo que oculta las estrellas débiles: las noches sin Luna son las mejores para ver las constelaciones.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'interactivo', '{"componente": "cielo-esta-noche", "etiqueta": "Interactivo", "modelo": "Observación: el cielo de cualquier noche", "pie": "El cielo calculado para la fecha, la hora y el lugar elegidos. Estrellas y constelaciones: d3-celestial de Olaf Frohn (catálogo Hipparcos). Sol, Luna y planetas: método de cálculo de Paul Schlyter."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'texto', '{"html": "<h3>Saltos de estrella: de una estrella conocida a otra</h3>\n<p>Nadie aprende el cielo estrella a estrella. Se aprende a reconocer unas pocas figuras muy llamativas y, desde ellas, se «salta» a las demás siguiendo líneas imaginarias. Es lo que los aficionados llaman saltar de estrella en estrella.</p>\n<p>Para medir esos saltos se usa la mano, con el brazo bien estirado:</p>\n<ul><li><p>El dedo meñique tapa unos <strong>1°</strong>.</p></li><li><p>Tres dedos juntos, unos <strong>5°</strong>.</p></li><li><p>El puño cerrado, unos <strong>10°</strong>.</p></li><li><p>La mano abierta, del pulgar al meñique, unos <strong>20°</strong>: es el palmo.</p></li></ul>\n<p>Las medidas varían un poco de una persona a otra, pero como quien tiene la mano más grande suele tener también el brazo más largo, se compensan bastante.</p>\n<p>El interactivo recoge las rutas más útiles, cada una con la época y el hemisferio en que se ve: del Carro a Polaris, del Carro a Arturo y Espiga, del cinturón de Orión a Sirio y Aldebarán, los triángulos de verano y de invierno, y de la Cruz del Sur al polo sur celeste.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'interactivo', '{"componente": "saltos-estrella", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "Elige una ruta y avanza paso a paso. El mapa tiene el norte arriba y el este a la izquierda, como el cielo al mirar hacia arriba."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 6, 'texto', '{"html": "<h3>Practica la regla de la mano</h3>\n<p>La regla de la mano solo sirve si se practica. El interactivo de este apartado te muestra parejas de estrellas conocidas y te pide que adivines con qué parte de la mano taparías la distancia entre ellas. Después te enseña la medida real, en grados y en dedos o puños.</p>\n<p>A las medidas de antes se puede añadir una más: <strong>dos dedos juntos</strong>, el índice y el corazón, tapan unos <strong>3°</strong>.</p>\n<p><strong>Cómo comprobar tu propia mano.</strong> Usa distancias que todo el mundo puede ver. Los punteros del Carro, Merak y Dubhe, están a unos 5°: deberían caber en tres dedos. Las tres estrellas del cinturón de Orión ocupan casi 3°. De Betelgeuse a Rigel hay casi 19°, más o menos un palmo. Si tu mano da algo más o algo menos, apúntalo y corrígelo a partir de entonces.</p>\n<p><strong>Cómo medir la altura de un astro.</strong> Apoya el borde del puño en el horizonte y ve poniendo un puño encima de otro, alternando las manos, hasta llegar al astro. Cada puño son unos 10°. Del horizonte al cenit hay 90°: unos nueve puños.</p>\n<p>Lo que se mide así son ángulos: cuánto hay que girar la vista para ir de un punto a otro. Es lo que se observa, y todos los modelos del mundo aceptan esas medidas. En lo que difieren es en a qué distancia real corresponden: en el modelo del globo, las estrellas están tan lejos que esos ángulos son iguales desde cualquier lugar de la Tierra; en el modelo plano, los astros están mucho más cerca y su tamaño y su altura se explican por la perspectiva.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 7, 'interactivo', '{"componente": "medir-mano", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "Elige cuánto crees que hay entre las dos estrellas y compruébalo. Las distancias se calculan con las posiciones del catálogo Hipparcos (d3-celestial)."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 8, 'texto', '{"html": "<h3>Las constelaciones de cada estación</h3>\n<p>Si sales a la misma hora cada noche, verás que el cielo no es siempre el mismo. Cada estrella sale unos cuatro minutos antes que la noche anterior: unas dos horas antes cada mes. Por eso, a lo largo del año, por el cielo de las diez de la noche desfilan todas las constelaciones que se pueden ver desde tu latitud. Las que rodean el polo, las llamadas <strong>circumpolares</strong>, no se ponen nunca y se ven todo el año: en el norte, la Osa Mayor y Casiopea; en el sur, la Cruz del Sur desde latitudes como las de Buenos Aires o Santiago.</p>\n<p>Las estaciones están invertidas entre los dos hemisferios: cuando en Madrid es invierno, en Buenos Aires es verano. Pero el cielo de enero a las diez de la noche tiene a Orión en lo alto en los dos sitios: alto hacia el sur visto desde el norte, y alto hacia el norte, «cabeza abajo», visto desde el sur.</p>\n<ul><li><p><strong>Enero</strong>: Orión, Tauro con las Pléyades, Géminis, el Perro Mayor con Sirio y el Cochero con Capela. Desde el sur, además, Canopo, la segunda estrella más brillante de la noche, casi encima.</p></li><li><p><strong>Abril</strong>: Leo, Virgo, el Boyero con Arturo y la Osa Mayor muy alta en el norte. Desde el sur, la Cruz del Sur y Centauro en su mejor momento.</p></li><li><p><strong>Julio</strong>: el triángulo de verano (Vega, Deneb y Altair), Escorpio con Antares y Sagitario. Desde el sur, Escorpio pasa casi por encima de la cabeza.</p></li><li><p><strong>Octubre</strong>: Pegaso con su gran cuadrado, Andrómeda, Casiopea y Perseo. Desde el sur, Fomalhaut, Achernar y las dos Nubes de Magallanes.</p></li></ul>\n<p>El interactivo muestra el cielo de mediados de cada uno de esos meses a las diez de la noche, desde una latitud media del norte o del sur, con esas figuras resaltadas. No incluye los planetas, porque cambian de sitio de un año a otro: para verlos, usa el mapa del cielo de esta noche.</p>\n<p><strong>Cómo lo explica cada modelo.</strong> Lo que se observa es que la bóveda de las estrellas da una vuelta completa en 23 horas y 56 minutos, cuatro minutos menos que el Sol. En el modelo del globo, se debe a que la Tierra, además de girar sobre sí misma, recorre su órbita alrededor del Sol, y cada noche mira hacia una parte un poco distinta del espacio. En el modelo plano, a que las estrellas y el Sol giran sobre el plano a velocidades ligeramente distintas. En los modelos geocéntricos antiguos, a que el Sol avanza cada día un grado hacia el este por la eclíptica, sobre la esfera de las estrellas, y tarda un año en dar la vuelta completa.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 9, 'interactivo', '{"componente": "cielo-estaciones", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "El cielo hacia las 22:00 de mediados de cada mes, desde 40° N o 34° S, con las figuras de la estación resaltadas. Estrellas y constelaciones: d3-celestial de Olaf Frohn (catálogo Hipparcos)."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 10, 'texto', '{"html": "<h3>Encontrar los puntos cardinales sin brújula</h3>\n<p><strong>De noche, en el hemisferio norte.</strong> Busca Polaris con el salto desde el Carro. Bajo ella, en el horizonte, está el norte. A tu espalda queda el sur, a tu derecha el este y a tu izquierda el oeste.</p>\n<p><strong>De noche, en el hemisferio sur.</strong> Busca el polo sur celeste con la Cruz del Sur y los punteros de Centauro. Bajo ese punto, en el horizonte, está el sur.</p>\n<p><strong>De noche, en cualquier lugar.</strong> Mintaka, la estrella del cinturón de Orión más cercana a Aldebarán, está casi sobre el ecuador celeste: desde cualquier lugar de la Tierra sale prácticamente por el este y se pone por el oeste.</p>\n<p><strong>De día, con la sombra de un palo.</strong> Clava un palo recto en el suelo, marca con una piedra la punta de su sombra, espera entre quince minutos y media hora y marca de nuevo la punta. La primera marca queda al oeste y la segunda al este: la línea que las une va de oeste a este. Si te pones con la primera marca a la izquierda y la segunda a la derecha, miras al norte. Funciona en cualquier latitud y en cualquier época del año, y el interactivo de este apartado te deja probarlo.</p>\n<p><strong>De día, con el Sol a mediodía.</strong> Fuera de la franja de los trópicos, cuando el Sol está en su punto más alto del día marca el sur si estás en el hemisferio norte, y el norte si estás en el sur. Es el momento en que las sombras son más cortas. Ese mediodía solar no coincide exactamente con las 12 del reloj: según el lugar y el horario de verano, puede caer más cerca de la una o de las dos de la tarde.</p>\n<p><strong>Con un reloj de agujas.</strong> En el hemisferio norte, apunta la aguja de las horas hacia el Sol: el sur queda a mitad de camino entre esa aguja y las 12 (o la 1, si rige el horario de verano). En el hemisferio sur, apunta las 12 hacia el Sol: el norte queda a mitad de camino entre las 12 y la aguja de las horas. Es un método aproximado.</p>\n<p><strong>Con la Luna.</strong> La parte iluminada de la Luna siempre mira hacia donde está el Sol, aunque el Sol ya se haya puesto. Por eso la Luna creciente de la tarde tiene su lado brillante hacia el oeste, y la menguante del amanecer, hacia el este. De forma aproximada, en el hemisferio norte, si unes las dos puntas de una Luna creciente o menguante y prolongas esa línea hasta el horizonte, señala más o menos hacia el sur.</p>\n<p><strong>Cómo lo explica cada modelo.</strong> Para el modelo del globo, estas técnicas funcionan porque la Tierra gira sobre un eje que apunta hacia los polos celestes, y por eso el Sol y las estrellas parecen girar a su alrededor. Para el modelo plano, funcionan porque el Sol y las estrellas giran por encima del plano alrededor del centro, sobre el que está Polaris. Para los modelos de esferas antiguos, porque la esfera celeste gira cada día alrededor de la Tierra inmóvil. Todos coinciden en lo que se ve, y por eso la orientación por el cielo se ha practicado en todas las culturas.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 11, 'interactivo', '{"componente": "sombra-palo", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "Un palo visto desde arriba y el recorrido de la punta de su sombra a lo largo del día. Mueve la hora de la primera marca y cambia de lugar y de estación."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 11;
insert into public.secciones (modulo_id, orden, slug, titulo) select id, 12, 'practicar-bajo-el-cielo-calendario-y-misiones', 'Practicar bajo el cielo: calendario y misiones' from public.modulos where numero = 1;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 1, 'texto', '{"html": "<p>La mejor manera de aprender el cielo es salir a mirarlo con un propósito. Esta sección te da dos herramientas: un calendario de lo que va a pasar en el cielo durante el próximo año, y una lista de misiones de observación para hacer a tu ritmo.</p>\n<p>Las dos se basan en lo que cualquiera puede ver. Te proponemos anotar primero lo que ves, con la fecha, la hora y el lugar, y solo después pensar en cómo lo explicaría cada modelo. Así cada observación es tuya, y puedes usarla para contrastar las explicaciones que has visto en este módulo.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 12;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 2, 'texto', '{"html": "<h3>Calendario del cielo</h3>\n<p>El calendario se calcula en tu propio dispositivo y empieza en la fecha de hoy. Incluye:</p>\n<ul><li><p><strong>Las fases de la Luna</strong>: luna nueva, cuarto creciente, luna llena y cuarto menguante, con su hora.</p></li><li><p><strong>Los equinoccios y los solsticios</strong>: los cuatro momentos del año en que cambian las estaciones.</p></li><li><p><strong>Los planetas</strong>: cuándo Marte, Júpiter y Saturno están en <strong>oposición</strong> (en el lado del cielo contrario al Sol, visibles toda la noche y en su máximo brillo), cuándo Venus y Mercurio se ven más separados del Sol, y cuándo dos planetas se ven muy juntos.</p></li><li><p><strong>La Luna junto a los planetas</strong>: las noches en que la Luna pasa al lado de Venus, Marte, Júpiter o Saturno. Es la forma más fácil de encontrar un planeta por primera vez.</p></li><li><p><strong>Los eclipses</strong> de Sol y de Luna, con las zonas de la Tierra desde donde se ven.</p></li><li><p><strong>Las lluvias de estrellas</strong>, con la fecha aproximada de su máximo y un aviso si ese año la Luna llena va a estorbar.</p></li></ul>\n<p>Puedes elegir qué tipos de fenómenos ver y añadir cualquiera de ellos, o todos, al calendario de tu móvil o de tu ordenador.</p>\n<p>De dónde salen los datos: las posiciones del Sol, la Luna y los planetas se calculan con el método de Paul Schlyter, que tiene una precisión de alrededor de un minuto de arco. Las fechas y las zonas de visibilidad de los eclipses son las del catálogo de la NASA preparado por Fred Espenak, que llega hasta 2030 en este calendario. Las fechas de las lluvias de estrellas son las habituales del máximo según la Organización Internacional de Meteoros, y pueden variar un día de un año a otro.</p>\n<p><strong>Una advertencia importante.</strong> Nunca mires el Sol directamente, tampoco durante un eclipse parcial o anular: solo con gafas de eclipse homologadas, con la norma ISO 12312-2. Las gafas de sol, los cristales ahumados y las radiografías no protegen. Los eclipses de Luna, en cambio, se pueden mirar sin ninguna protección.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 12;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 3, 'interactivo', '{"componente": "calendario-cielo", "etiqueta": "Interactivo", "modelo": "Observación", "pie": "Calculado en tu dispositivo para los doce meses siguientes. Sol, Luna y planetas: método de Paul Schlyter. Eclipses: NASA (Fred Espenak). Lluvias de estrellas: Organización Internacional de Meteoros."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 12;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 4, 'texto', '{"html": "<h3>Misiones de observación</h3>\n<p>Cada misión te pide observar algo concreto y anotar lo que ves. Están ordenadas de más fácil a más larga. En el cuaderno del interactivo puedes marcarlas como hechas y escribir tus notas, que se guardan en tu navegador.</p>\n<p><strong>Misión 1. Encuentra el norte o el sur de tu casa.</strong> Una noche despejada, localiza Polaris con el salto desde el Carro si vives en el hemisferio norte, o el polo sur celeste con la Cruz del Sur si vives en el sur. Fíjate qué edificio, árbol o montaña queda debajo. Desde ese día sabrás dónde está el norte o el sur desde tu ventana, sin brújula.</p>\n<p><strong>Misión 2. Mide tu latitud con la mano.</strong> Mide en puños la altura de Polaris sobre el horizonte, o la del punto del polo sur celeste. Multiplica por diez y compáralo con la latitud de tu ciudad, que puedes buscar en un mapa. Si estás en Madrid, deberían salirte unos cuatro puños: 40°. Anota cuánto te has desviado.</p>\n<p><strong>Misión 3. Recorre los saltos de estrella de la estación.</strong> Elige en el interactivo de las estaciones el mes en el que estás y sal a buscar sus figuras principales. Después, haz los saltos de estrella que se vean esa noche. Anota cuáles has encontrado.</p>\n<p><strong>Misión 4. Sigue a la Luna durante una semana.</strong> Empieza dos o tres días después de la luna nueva, cuando se ve una Luna fina al atardecer. Cada noche, a la misma hora, anota dónde está, a cuántos puños del horizonte y qué forma tiene. Verás que cada día está más de un puño más al este y que su parte iluminada crece, siempre del lado donde se ha puesto el Sol.</p>\n<p><strong>Misión 5. Comprueba que las estrellas madrugan.</strong> Elige una estrella brillante cerca del horizonte y un punto fijo, como una antena o la esquina de un tejado. Anota la hora exacta a la que la estrella desaparece tras él. Repite una semana después desde el mismo sitio: ocurrirá unos 28 minutos antes, cuatro minutos por día.</p>\n<p><strong>Misión 6. Distingue un planeta de una estrella.</strong> Busca en el mapa del cielo de esta noche un planeta visible. Obsérvalo y fíjate en que centellea menos que las estrellas de alrededor. Dibuja su posición respecto a las estrellas cercanas, y repite el dibujo una o dos semanas después: verás que se ha desplazado, mientras que las estrellas siguen igual entre sí. Por eso los antiguos los llamaban astros errantes.</p>\n<p><strong>Misión 7. Encuentra el mediodía con la sombra de un palo.</strong> Un día de sol, clava un palo recto y marca la punta de su sombra cada quince minutos alrededor del mediodía. La marca más cercana al palo te da el mediodía solar y la dirección norte-sur. Anota la hora del reloj: verás que no coincide con las doce.</p>\n<p><strong>Misión 8. Sigue al Sol por el horizonte.</strong> Desde el mismo sitio, fotografía la puesta de Sol una vez cada dos semanas, con el mismo encuadre y alguna referencia en el horizonte. Al cabo de unos meses verás que el Sol se pone cada vez más a un lado, se detiene en los solsticios y vuelve. Es lo que hicieron los constructores de muchos monumentos antiguos alineados con el Sol.</p>\n<p><strong>Misión 9. Cuenta estrellas fugaces.</strong> Busca en el calendario la próxima lluvia de estrellas, aléjate de las luces y túmbate mirando hacia arriba durante una hora. Cuenta cuántas ves y fíjate de qué zona del cielo parecen salir: es el radiante, que da nombre a la lluvia.</p>\n<p><strong>Misión 10. Fotografía el giro del cielo.</strong> Sigue los pasos del apartado «Compruébalo tú mismo», en la sección sobre el movimiento de las estrellas, y consigue tu propia foto de los arcos alrededor del polo. Anota la dirección y la inclinación a la que apuntaste la cámara.</p>"}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 12;
insert into public.bloques (seccion_id, orden, tipo, contenido) select s.id, 5, 'interactivo', '{"componente": "misiones", "etiqueta": "Interactivo", "modelo": "Tu cuaderno de observación", "pie": "Marca las misiones que vayas haciendo y apunta tus notas. Se guardan solo en este navegador."}'::jsonb from public.secciones s join public.modulos m on m.id = s.modulo_id where m.numero = 1 and s.orden = 12;
